  assert.deepEqual(filaDeOperacoes([1, 2], 'unshift', 0), [0, 1, 2]);
});

test('pop e shift removem itens', () => {
  assert.deepEqual(filaDeOperacoes([1, 2, 3], 'pop'), [1, 2]);
  assert.deepEqual(filaDeOperacoes([1, 2, 3], 'shift'), [2, 3]);
});

test('remover de uma lista vazia devolve lista vazia', () => {
  assert.deepEqual(filaDeOperacoes([], 'pop'), []);
  assert.deepEqual(filaDeOperacoes([], 'shift'), []);
});

test('operação desconhecida lança erro', () => {
  assert.throws(() => filaDeOperacoes([1], 'trocar', 2));
});

solutionCode:
export function filaDeOperacoes(lista, operacao, valor) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  if (operacao === 'push') {
    lista.push(valor);
    return lista;
  }
  if (operacao === 'pop') {
    lista.pop();
    return lista;
  }
  if (operacao === 'shift') {
    lista.shift();
    return lista;
  }
  if (operacao === 'unshift') {
    lista.unshift(valor);
    return lista;
  }
  throw new Error('operação desconhecida: ' + operacao);
}
